import copy, hashlib, json, pathlib, uuid

ROOT = pathlib.Path('/home/enpasos/projects/skillpilot').resolve()
BASE = ROOT / 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-10/wirtschaft-M4-seven-work-career-two-case-whole-materials-author-a-v1'
INTAKE = ROOT / 'curricula/DE/Gymnasium/quality/goal-evidence/2026-10-10/wirtschaft-M4-seven-work-career-whole-contracts-KEEP-first-root-author-intake-v1/whole-seven-current524-DEEN-work-career-contracts-all-original-P-existing-material-intake.json'
BASE.mkdir(exist_ok=True)
assert BASE.resolve() == BASE and BASE.is_relative_to(ROOT)
intake = json.loads(INTAKE.read_text())
contracts = intake['wholeCurrent7ContractsAndP']

def bind(p):
    b = p.read_bytes()
    return {'path': str(p.relative_to(ROOT)), 'sha256': hashlib.sha256(b).hexdigest(), 'bytes': len(b)}

def put(name, value):
    p = BASE / name
    assert p.parent.resolve() == BASE and not p.exists()
    p.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n')
    return bind(p)

# Each row is one actual task with four separately observable marks.
def step(de, en, solde, solen, criteria):
    assert len(criteria) == 4
    return dict(taskDe=de, taskEn=en, solutionDe=solde, solutionEn=solen, fourMarksDe=criteria)

materials = []
rows = []

def material(index, slug, title, titleen, description, descriptionen, data, dataen, tasks, corede, coreen, phase):
    g = contracts[index]['wholeGoal']
    assert len(tasks) == 6
    mid = str(uuid.uuid5(uuid.NAMESPACE_URL, 'skillpilot:economics:work-career:2026-10-10:' + slug))
    commonde = '24 Punkte, bestanden ab 15. Alle Betriebe, Profile, Institutionen, Löhne und Regelungen sind eigene fiktive Unterrichtsmodelle; ausdrücklich verlinkte BAuA-Berichte sind die einzigen empirischen Quellen. Bearbeite beide eigenständigen Fälle. Persönliche Angaben, Bewerbungen, Beratungskontakte oder Kontaktaufnahmen sind nicht erforderlich. Bei Reflexionsfragen darfst du das bereitgestellte ausdrücklich simulierte Profil übernehmen oder freiwillig ausgewählte eigene Bezugspunkte nutzen; private Angaben bleiben lokal.'
    commonen = '24 points, pass at 15. Firms, profiles, institutions, wages and rules are original fictional teaching models; explicitly linked BAuA reports are the only empirical sources. Address both independent cases. No personal details, applications, advice contacts or real outreach are required. Reflection may use the supplied explicitly simulated profile or voluntarily selected personal points; private details stay local.'
    fairde = 'Bewertung der ganzen Arbeit: Nachvollziehbare unvollständige Leistungen und begründete alternative Urteile zählen. Eine fachliche Leistung darf an anderer Stelle derselben Arbeit gezeigt sein; Aufgabenüberschriften sind keine Pflicht. Ein isolierter Rechen-, Rundungs-, Schreib- oder Detailfehler löst keine Gesamtbegrenzung aus. ' + corede
    fairen = 'Assess the whole submission: meaningful incomplete performance and justified alternative judgements earn marks. Relevant evidence may occur elsewhere in the same work; task headings are not compulsory. An isolated arithmetic, rounding, spelling or detail error triggers no total limit. ' + coreen
    taskde = f'**{title} — {commonde}**\n\n{data}\n\n**Aufgaben, jeweils 4 Punkte.**\n' + '\n'.join(f'{n}. {t["taskDe"]}' for n,t in enumerate(tasks,1)) + '\n\n' + fairde
    tasken = f'**{titleen} — {commonen}**\n\n{dataen}\n\n**Tasks, 4 points each.**\n' + '\n'.join(f'{n}. {t["taskEn"]}' for n,t in enumerate(tasks,1)) + '\n\n' + fairen
    solde = '\n\n'.join(f'{n}. {t["solutionDe"]}\nBewertung: je 1 Punkt für ' + '; '.join(t['fourMarksDe']) + '.' for n,t in enumerate(tasks,1)) + '\n\n' + fairde
    solen = '\n\n'.join(f'{n}. {t["solutionEn"]}' for n,t in enumerate(tasks,1)) + '\n\nEach numbered solution identifies four separate assessable elements, worth one point each; coherent partial evidence earns the corresponding marks.\n\n' + fairen
    m = {'id':mid, 'title':title, 'titleEn':titleen, 'description':description, 'descriptionEn':descriptionen, 'weight':1, 'tags':(['LK'] if index==2 else ['GK','LK'])+['Practice','Assessment'], 'contains':[], 'requires':[g['id']], 'type':'atomic', 'phase':phase, 'dimensionTags':{'framework':'canonical-gymnasium-economics','demandLevel':'AB3','phase':phase}, 'applicability':copy.deepcopy(g['applicability']), 'extendedData':{'applicabilityFromRequires':True}, 'examData':{'reviewStatus':'draft','coveredGoalIds':[g['id']], 'coveredStrands':['WW_WIRTSCHAFT','WW_GESELLSCHAFT'], 'demandLevels':['AB1','AB2','AB3'], 'taskContent':taskde,'taskContentEn':tasken,'solutionContent':solde,'solutionContentEn':solen,'scoring':{'maxPoints':24,'passingPoints':15,'steps':[{'id':f's{n}','points':4,'description':'Je 1 Punkt: '+'; '.join(t['fourMarksDe'])+'.'} for n,t in enumerate(tasks,1)]}}}
    materials.append(m)
    rows.append({'materialId':mid,'wholeGoalId':g['id'],'wholeOriginalP':copy.deepcopy(contracts[index]['wholeOriginalP']),'actualTwoCases':True,'wholeTaskSolutionFourMarkCriteria':tasks,'necessaryCoreBoundaryDe':corede,'necessaryCoreBoundaryEn':coreen,'scopeAndReleaseIndependentReviewPending':True})

material(0,'labour-models','Q2: NAIRU, Tarifwege und unsichere Modellschwellen','Q2: NAIRU, bargaining channels and uncertain thresholds',
'Die lernende Person kann zwei bereitgestellte Arbeitsmarktmodelle und Tarifkontexte mit Rechnungen, Wirkungskanälen und Schätzgrenzen erklären.',
'The learner can explain two supplied labour-market models and bargaining contexts using calculations, transmission channels and estimation limits.',
'**A — schwache Nachfrage.** Modell: Δπ = −0,5(u−u*), u*=6%, beobachtetes u=8%, bisherige Inflation 3%. Δπ ist die Änderung der Inflationsrate in Prozentpunkten; die Quoten werden als Prozentzahlen eingesetzt. u* ist eine unsichere Schätzung. Tariflohn steigt von 20 auf 21 Euro je Stunde, Output je Stunde bleibt 10 Stück. Beschäftigte konsumieren einen Teil zusätzlicher Einkommen; der Betrieb kann Preise, Marge oder Produktion verändern.\n\n**B — koordinierter Abschluss nach Erholung.** Tariflohn wächst um 4%, Output je Stunde um 2%, Preise um 3%. Modell Δπ=−0,4(u−u*), beobachtetes u=5%; ursprüngliches u*=6%, später auf 5% revidiert. Auch die Revision ist eine Schätzung. Die Betriebe haben unterschiedliche Margen; koordinierte Verhandlungen können Erwartungen abstimmen, sichern aber keinen Nachfrage- oder Beschäftigungspfad.',
'**A — weak demand.** Model: Δπ = −0.5(u−u*), u*=6%, observed u=8%, previous inflation 3%. Δπ is the inflation-rate change in percentage points; enter the unemployment rates as percentage numbers. u* is uncertainly estimated. Hourly pay rises from EUR20 to21; hourly output remains10 units. Workers consume part of extra incomes; the firm may change prices, margins or production.\n\n**B — coordinated agreement after recovery.** Pay rises4%, hourly output2%, prices3%. Model Δπ=−0.4(u−u*), observed u=5%; initial u*=6%, revised estimate5%. Revision remains estimation. Firms have different margins; coordination may align expectations but guarantees no demand/employment path.',
[
step('Erkläre NAIRU und berechne für A Δπ sowie die neue Inflationsrate. Ist u*=6% eine direkt beobachtete oder politisch wünschenswerte Quote?', 'Explain NAIRU, calculate A’s Δπ and resulting inflation, and distinguish the estimate from observed or politically desirable unemployment.', 'NAIRU bezeichnet hier die geschätzte Modellschwelle ohne beschleunigende Inflation. Δπ=−1 Prozentpunkt und neue Inflation2%; Preise steigen weiterhin. u*=6% ist weder beobachtete tatsächliche Quote noch normatives Beschäftigungsziel.', 'NAIRU is the estimated model threshold for non-accelerating inflation. Δπ=−1 percentage point and resulting inflation2%; prices still rise. Six percent is neither the observed rate nor a normative employment target.', ['nicht beschleunigende Inflation als Bedeutung','Δπ=−1 Prozentpunkt','neue Inflation2% statt Preisrückgang','Schätzgröße weder beobachtete Quote noch politisches Soll']),
step('Berechne A-Stücklohnkosten vorher/nachher und erkläre je einen Kosten-/Preis- und Einkommens-/Nachfragekanal mit Bedingung.', 'Calculate A’s old/new unit labour costs and explain a cost/price and an income/demand channel with conditions.', '20/10=2 und21/10=2,10Euro pro Stück, +5%. Preisüberwälzung hängt etwa von Wettbewerb/Nachfrage ab; sonst kann die Marge sinken. Höheres Einkommen kann Konsum erhöhen, abhängig von Sparverhalten, Preisen und Beschäftigung.', 'Costs rise from20/10=2 to21/10=2.10 per unit, +5%. Competition/demand affect pass-through, otherwise margins may fall. Higher income may support consumption depending on saving, prices and employment.', ['richtige Stückkostenrechnung','Kosten-/Preiskanal','Einkommens-/Nachfragekanal','begründete konkrete Bedingung statt Automatismus']),
step('Prüfe die Behauptung „Das Modell beweist, dass ein Tarifplus Arbeitsplätze vernichtet und genau6% Arbeitslosigkeit erforderlich sind“. Begründe ein bedingtes Urteil für A und eine zusätzlich benötigte Information.', 'Assess “The model proves a pay rise destroys jobs and exactly6% unemployment is required”; give a conditional judgement for A and identify missing evidence.', 'Das vorgegebene Inflationsmodell enthält keine sichere Beschäftigungsreaktion des Tarifabschlusses. Kostendruck und Nachfrage können gegenläufig wirken; Margen, Auftragslage oder Marktform müssten geprüft werden. Die unsichere Schwelle ist kein politischer Auftrag; Begründung beider Grenzen zählt.', 'The supplied inflation model identifies no certain bargaining-induced employment response. Costs and demand may work differently; examine margins, orders or market structure. An uncertain threshold is no policy mandate; justify both limits.', ['Inflationsmodell von Beschäftigungsprognose getrennt','gegenläufige Tarifwege fallbezogen','Schätz-/Sollgrenze begründet','konkreter zusätzlicher Datenbedarf']),
step('Berechne B-Stückkosten- und Reallohnänderung. Erkläre, warum weder beide4% noch derselbe Quotient sind.', 'Calculate B’s unit-cost and real-pay changes and explain their distinct denominators.', '1,04/1,02−1≈1,96% Stückkosten;1,04/1,03−1≈0,97% Reallohn. Produktivität ist Stückkosten-, Preisniveau Kaufkraftnenner; nominal4% ist anders. Sinnvolles Runden zählt.', 'Unit costs:1.04/1.02−1≈1.96%; real pay:1.04/1.03−1≈0.97%. Productivity is the cost denominator and prices the purchasing-power denominator; nominal4% differs.', ['Stückkosten≈1,96%','Reallohn≈0,97%','Produktivitätsnenner erklärt','Preisnenner gegenüber nominalem Lohn erklärt']),
step('Rechne B-Δπ mit alter und revidierter Schätzung. Deute die Revision und einen möglichen Einfluss koordinierter Tarifverhandlungen.', 'Calculate B’s Δπ using both estimates, interpret revision and one possible coordination mechanism.', 'Mit6% ergibt sich+0,4 Prozentpunkt, mit5%0. Revision verändert Modelldeutung, beweist aber keine gemessene Naturkonstante oder tatsächliche Inflationsänderung. Koordination kann Lohn-/Preiserwartungen abstimmen; Wirkung braucht passende Nachfrage-/Produktivitätsbedingungen.', 'The old estimate gives+0.4 percentage point and the revision0. Revision changes interpretation without proving a measured natural constant or actual inflation change. Coordination may align wage/price expectations subject to demand/productivity conditions.', ['alte Prognose+0,4','revidierte Prognose0','Revision als unsichere Schätzung','Koordination mit begründetem Wirkungskanal']),
step('Beurteile für B die Aussage „Revidierte NAIRU und steigender Reallohn garantieren mehr Beschäftigung“. Nenne eine plausible andere Entwicklung und prüfbare Information.', 'Assess “A revised NAIRU and rising real pay guarantee more employment”; identify an alternative development and testable information.', 'Keine Garantie: stärkere Nachfrage kann Beschäftigung stützen, aber schwache Aufträge/geringe Margen können andere Reaktionen auslösen. Der Schätzwert allein misst keinen kausalen Tarif- oder Jobeffekt. Eine begründete Prüfung von Aufträgen, Lohnkosten/Output und zeitlicher Schätzung ist erforderlich.', 'No guarantee: demand may support employment, while weak orders/margins may imply other responses. An estimate alone measures no causal agreement/job effect. Specify evidence on orders, costs/output and estimation dates.', ['begründete Beschäftigungsgrenze','plausible alternative Entwicklung','Modellschätzung von Kausalbeweis getrennt','gezielte prüfbare Information'])
], 'Fehlt die NAIRU-/Modellschwellen-Deutung vollständig oder ist sie durchgehend falsch, oder fehlen über die ganze Arbeit sämtliche fallbezogenen tariflichen Wirkungskanäle, sind höchstens14 Punkte möglich. Echte unsichere oder unvollständige Deutung erhält Teilpunkte.', 'Wholly absent/consistently wrong interpretation of the NAIRU/model threshold, or no case-based bargaining channels anywhere, limits the total to14. Meaningful uncertain/incomplete interpretation earns marks.', 'Q2')

material(1,'bargaining-disputes','Q2: Kaufkraftkonflikt und planbare Schichten','Q2: purchasing-power disputes and predictable shifts',
'Die lernende Person kann einen Lohn- und einen Arbeitszeitkonflikt anhand beider Tarifparteien, realer Größen und bedingter wirtschaftlicher Folgen analysieren.',
'The learner can analyse a pay dispute and an hours dispute using both bargaining parties, real quantities and conditional economic effects.',
'**A — Lohnverhandlung.** Gewerkschaft: Kaufkraftverlust begrenzen und Einkommen sichern. Arbeitgeberverband: Stückkosten, Wettbewerb und Aufträge beachten. Tariflohn bisher25Euro/Stunde; Abschluss+4%, Preise+5%, Produktivität+2%. Nachfrage ist unsicher; Preise lassen sich nicht beliebig erhöhen.\n\n**B — Zulieferbetrieb.** Im Mittelpunkt stehen kurzfristige Schichtänderungen und Einkommenssicherheit, kein pauschales Lohnplus. Ein befristeter Streik verhindert200Teile pro Tag an2Tagen; Abnehmer hat300Teile Puffer und benötigt200pro Tag, danach keine Ersatzlieferung. Kompromiss: Dienstplan14Tage vorher, Änderungen nur in gemeinsam vereinbarten Ausnahmen; Beschäftigungszusage12Monate bei erfüllten Auftragsannahmen, flexiblere Schichtlage bei gleichem Stundenumfang. Alle Bedingungen sind fiktiv, keine aktuelle Rechtsauskunft.',
'**A — pay bargaining.** Union: limit purchasing-power loss and protect income. Employer association: costs, competition and orders. Previous pay EUR25/hour; agreement+4%, prices+5%, productivity+2%. Demand is uncertain; prices cannot rise without limit.\n\n**B — supplier.** Unexpected roster changes and income security are central, not a general pay rise. A temporary strike stops200parts/day for2days; the customer has300parts in stock and needs200/day, with no substitute delivery. Compromise: rosters14days ahead, changes only under jointly agreed exceptions;12-month employment assurance subject to stated order assumptions and more flexible shift timing at unchanged total hours. All rules are fictional, not current legal advice.',
[
step('Analysiere A-Parteien, Streitpunkt und je ein Macht-/Rahmenmerkmal. Begründe, warum der Abschluss ein Kompromiss sein kann.', 'Analyse A’s parties, issue and one power/context factor each; explain a possible compromise.', 'Gewerkschaft vertritt Einkommen/Kaufkraft, Arbeitgeber Kosten/Wettbewerb. Organisation/Arbeitskampf und Nachfrage-/Alternativen beeinflussen Macht, sind keine sicheren Siegerregeln.4% kann weniger Kosten als höhere Forderung und mehr Einkommen als Stillstand bieten, ohne vollen Kaufkraftschutz.', 'The union seeks income/purchasing power; employers costs/competition. Organisation/industrial action and demand/alternatives influence power without predetermined winners. Four percent may balance higher pay against costs without full purchasing-power protection.', ['Gewerkschaftsinteresse','Arbeitgeberinteresse','fallbezogene Macht-/Rahmenbedingung','bedingter Kompromiss']),
step('Berechne A-Nominallohn, Reallohn- und Stückkostenänderung; unterscheide die Bezugsgrößen.', 'Calculate A’s nominal pay, real-pay change and unit-cost change; distinguish bases.', 'Neuer Lohn26Euro. Reallohn1,04/1,05−1≈−0,95%; Stückkosten1,04/1,02−1≈+1,96%.26Euro und4%nominal garantieren keinen Kaufkraftzuwachs; Preise und Produktivität sind unterschiedliche Nenner.', 'New pay EUR26. Real pay1.04/1.05−1≈−0.95%; unit costs1.04/1.02−1≈+1.96%. Nominal pay does not guarantee increased purchasing power; prices and productivity are distinct denominators.', ['26Euro','Reallohn≈−0,95%','Stückkosten≈+1,96%','nominal/real/Kosten unterschieden']),
step('Erkläre für A zwei wirtschaftliche Wirkungsketten und einen bedingten Gesamtbefund, ohne automatische vollständige Preisüberwälzung.', 'Explain two economic chains in A and a conditional judgement without automatic full price pass-through.', 'Lohnkosten jeStück steigen→Marge/Preis/Investition können reagieren; Wettbewerb begrenzt Überwälzung. Einkommen nominal höher, Kaufkraft leicht geringer→Konsum hängt auch von Sparen/anderen Einkommen ab. Nachfrage/Produktivität entscheiden mit über Beschäftigung; beide Kanäle abwägen.', 'Higher unit costs may affect margins/prices/investment, with competition limiting pass-through. Nominal incomes rise but purchasing power slightly falls, so consumption depends on saving/other income. Demand/productivity also shape employment; weigh both channels.', ['Kostenkette','Nachfragekette','konkrete Überwälzungsbedingung','begründete bedingte Gesamtanalyse']),
step('Analysiere B-Interessen sowie unmittelbare und indirekte Streikfolgen. Berechne die fehlenden Teile beim Abnehmer nach zwei Tagen.', 'Analyse B’s interests and direct/indirect strike effects; calculate the customer’s two-day shortfall.', 'Beschäftigte suchen Planbarkeit/Sicherheit, Betrieb Kapazitätsflexibilität/Kostenkontrolle.400Teile fehlen beimZulieferer; Abnehmerbedarf400 minusPuffer300=100ungedeckt, Produktion/Lieferungen können ausfallen.100ist Modellbedarf, kein sicherer Umsatzverlust.', 'Workers seek predictable hours/security; the firm capacity flexibility/cost control. The supplier loses400parts; customer demand400 minus stock300 leaves100uncovered. Production/delivery may be delayed;100parts is not a proven revenue loss.', ['beide nichtmonetären Interessen','400fehlendeZulieferteile','100ungedeckterBedarf','indirekte Folge mit Grenze']),
step('Prüfe den B-Kompromiss auf Planbarkeit, Nachfrage und Umsetzbarkeit. Was ist mit unveränderten Gesamtstunden gewonnen und noch offen?', 'Evaluate B’s compromise for predictability, demand and implementation; explain unchanged total hours and open issues.', '14Tage verbessert Planung, vereinbarteAusnahmen müssen konkret umsetzbar sein. FlexiblereLage kann Abdeckung stützen, verringert aber Stunden nicht. Die12-Monatszusage hängt an Auftragsannahmen und ist keine ewige Beschäftigungsgarantie; Einkommens-/Belastungsverteilung bleibt zu klären.', 'Fourteen days supports planning; exceptions need workable agreement. Flexible timing may aid coverage but does not reduce total hours. The12-month assurance depends on orders and is no permanent guarantee; clarify income and burden allocation.', ['Planbarkeitsvorteil','Stundenlage≠Umfang','Auftrags-/Umsetzungsbedingung','Zusage von dauerhafter Garantie getrennt']),
step('Formuliere einen begründeten alternativen B-Kompromiss und zwei prüfbare Folgen. Erkläre, warum Tarifautonomie das wirtschaftliche Ergebnis nicht festlegt.', 'Give a justified alternative B compromise and two testable consequences; explain why bargaining autonomy fixes no economic outcome.', 'Etwa festes Grundraster plus freiwilliger Tausch mit Ausgleich/Fristen; dafür müssen Bedarf und faire Belastung geprüft werden. Folgen: weniger kurzfristigeÄnderungen, möglicherweise höhereAbdeckungskosten oder bessereBindung. EigenständigesAushandeln garantiert weder Absatz noch dauerhaftesEinkommen.', 'For example, fixed baseline rosters with voluntary swaps and agreed notice/compensation; assess demand and fairness. Test fewer sudden changes and possible coverage costs/retention. Autonomous bargaining guarantees neither sales nor permanent income.', ['begründete Alternative','eine Beschäftigtenfolge','eine Betriebs-/Partnerfolge','Tarifautonomie ohne Ergebnisgarantie'])
], 'Fehlt über die ganze Arbeit die tatsächliche Analyse beider Tarifparteien oder fehlen sämtliche begründeten wirtschaftlichen Wirkungsketten, gilt höchstens14. Bloß unvollständige Wirkungsabwägung oder ein Rechenfehler löst die Grenze nicht aus.', 'No actual analysis of both parties anywhere, or no justified economic chains, limits the total to14; an incomplete balance or arithmetic slip does not.', 'Q2')

material(2,'hours-participation','Q2: Stunden teilen, Mitsprache und variable Beteiligung','Q2: sharing hours, voice and variable participation',
'Die lernende Person kann in zwei Fällen Arbeitszeit- und Beteiligungsmodelle hinsichtlich Stunden, Köpfen, Einkommen und bedingten Beschäftigungswirkungen analysieren.',
'The learner can analyse two working-time and participation models for hours, headcount, income and conditional employment effects.',
'**A — Auftragsrückgang.**100Beschäftigte arbeiten je40Stunden/Woche für20Euro/Stunde. Vorübergehend sind3200Stunden statt4000nötig, gleiche Produktivität. ModellK:32Stunden für alle, proportional bezahlt. ModellE:20Entlassungen,80Personen arbeiten weiter40Stunden. Im gemeinsam beratenen Plan äußern Beschäftigte Zeitwünsche; derBetrieb legt mit ihnen Abdeckungsregeln fest. Dies ist organisatorische Mitsprache, keine Kapital- oder Gewinnbeteiligung.\n\n**B — Service und Gewinnrisiko.**20Personen arbeiten weiterhin je40Stunden; Gleitzeit verändert nur die Lage. Zwischen10und14Uhr müssen täglich mindestens12Personen verfügbar sein. Eine neue Teamverteilung sieht14imFenster vor, die alte nur10. ModellF zahlt jedem sicher1000EuroZusatzvergütung/Jahr; ModellG verteilt freiwillig10%des Gewinngesamt an20Personen. Gegebene mögliche Gewinne:100000,200000oder0Euro; keine Wahrscheinlichkeiten. Keine Stimm-/Entscheidungsrechte ausG zugesagt. Regeln und Personalausstattung sind fiktiv.',
'**A — falling orders.**100workers each work40hours/week for EUR20/hour. Temporarily3200rather than4000hours are needed at unchanged productivity. K:32hours for everyone, proportional pay. E:20dismissals,80people still working40hours. In a jointly discussed roster, workers express preferences and agree coverage rules with management. This is organisational voice, not ownership/profit-sharing.\n\n**B — service and profit risk.**20people still work40hours each; flexitime changes timing only. At least12must be available daily10:00–14:00. New allocation provides14versus the old10. F pays each person a fixed EUR1000annual supplement; G voluntarily distributes10%of total profit across20people. Possible profits: EUR100000,200000or0, without probabilities. G grants no stated voting/decision rights. Rules and staffing are fictional.',
[
step('Berechne A-Stunden,40-Stunden-Vollzeitäquivalente und Köpfe inK/E. Erkläre den Unterschied.', 'Calculate A’s hours,40-hour full-time equivalents and headcounts in K/E; explain the difference.', 'K100×32=3200Stunden=80VZÄbei100Köpfen;E80×40=3200=80VZÄbei80Köpfen. VZÄist Stundenumrechnung, keine Kopfzahl; gleiche Stunden bedeuten keine gleiche Verteilung.', 'K100×32=3200hours=80FTEwith100people;E80×40=3200=80FTEwith80people. FTEconverts hours, not headcount; equal hours differ in distribution.', ['K3200Stunden','E3200Stunden','beide80VZÄ','100gegen80Köpfe begründet']),
step('Vergleiche A-Wocheneinkommen und Verteilung der Belastung. IstK kostenlose Arbeitsplatzsicherung?', 'Compare A’s weekly incomes/burden distribution; is K free job protection?', 'Vorher800Euro, K640EurojePerson(−20%), E800fürVerbleibende undkeinLohnvomBetriebfür20Entlassene; andereEinkommen unbekannt. KverteiltKürzung undhältKöpfe, kostet individuellEinkommen; ohneAufträge/Vertragsumsetzung keineSicherungsgarantie.', 'Previous pay800, K640per person(−20%), E800for remaining staff and no firm pay for20dismissed people; other income unknown. Kshares cuts/retains headcount but reduces income and requires orders/agreed implementation.', ['800und640','−20%fürK','BelastungsverteilungK/E','keine kostenlose oder garantierte Sicherung']),
step('Analysiere A-Mitsprache hinsichtlich Information, Koordination und Bindung. Nenne eine Bedingung und Nebenwirkung.', 'Analyse A’s employee voice for information, coordination and retention; name a condition and side effect.', 'Zeitwünsche liefernInformation undgemeinsameAbdeckung kannKoordination/Bindung stärken. FaireverlässlicheRegeln undtatsächlicheNachfrage sindBedingungen; Planung kostetZeit undunterschiedlicheWünsche könnenkonfligieren. Mitspracheändertnicht automatischLohn/Kopfzahl.', 'Preferences provide information; shared coverage can improve coordination/retention. Fair reliable rules and actual demand matter; planning takes time and preferences may conflict. Voice does not automatically change pay/headcount.', ['Informationskanal','Koordinations-/Bindungskanal','konkrete Bedingung','Nebenwirkung statt automatischer Beschäftigungseffekt']),
step('Prüfe B-Abdeckung und Gesamtstunden. Was verbessertGleitzeit und welche Beschäftigungsbehauptung folgt nicht?', 'Check B’s coverage and total hours; what can flexitime improve and what job claim does not follow?', '20×40=800Stundenweiterhin. Alt10unter12,Neu14mit2Puffer; dasallein beweistkeineAbdeckungandererZeiten. LageanpassungkannService/Passungverbessern, schafftaberwederautomatischmehrStundennochneueJobs; Bedarf/Restfenstermüssenpassen.', 'Total remains20×40=800hours. Old10misses12;new14gives2spare, without proving all other windows covered. Timing may improve service/fit but creates neither extra hours nor guaranteed jobs; examine demand and remaining periods.', ['800unveränderteStunden','10<12und14≥12','anderesAbdeckungsfensteroffen','Lageverbesserung ohne automatische Kopfzahlwirkung']),
step('Berechne G-Zahlung jePerson inallen drei Gewinnfällen, vergleicheF undtrenne finanzielle vonorganisatorischer Beteiligung.', 'Calculate G’s payment per person for each profit case, compare F and distinguish financial participation from voice.', '10%×100000/20=500,bei200000=1000,bei0=0Euro. Fsicher1000unterModellannahme;Gvariabel,beimittleremFallnichtgenerellgleich. Gewinnanteil allein liefertkeineStimmrechte/Mitsprache; tatsächlicheRegeln sindandersalsA.', 'Ggives0.10×100000/20=500,1000at200000,and0at zero profit. Fis fixed1000under the model; Gvaries. Aprofit share alone supplies no voting/voice rights, unlike A’s actual organisational rules.', ['500Euro','1000und0Euro','variablegegenfesteVergütung','finanzielleBeteiligung≠Entscheidungsmitsprache']),
step('Beurteile B-Anreize, Einkommensrisiko und mögliche Beschäftigungs-/Bindungswirkungen. Schlage eine bedingte faireRegel vor, ohne Erwartungswertzuerfinden.', 'Assess B’s incentives, income risk and possible employment/retention effects; propose a conditional fair rule without inventing expected values.', 'GkanngemeinsameErgebnisinteressen fördern,dochGewinnhängtauchvonFremdfaktorenab undgeradebeiSchwächefälltZusatzeinkommen. Bindung/ServicekönnenBeschäftigungstützen,nichtsichern. DenkbarfreiwilligeWahl/transparenteBerechnungmitBasisabsicherung;ohneWahrscheinlichkeitenkeinerwarteterBetrag.', 'Gmay align performance interests but profit also depends on outside factors and supplements vanish in weak periods. Retention/service may support, not guarantee jobs. Voluntary choice/transparent calculation with basic protection is defensible; no probabilities means no expected payment.', ['begründeterAnreiz','Einkommens-/Fremdfaktorrisiko','bedingteBeschäftigungs-/Bindungswirkung','faireRegel ohne erfundene Wahrscheinlichkeit'])
], 'Fehlt vollständig die Unterscheidung von Stunden und Köpfen oder jede tatsächliche Analyse von organisatorischer gegenüber finanzieller Beteiligung, sind höchstens14Punkte möglich. Eine einzelne falsche Zahl, unvollständige Nebenwirkung oder begründete andere Regel ist kein solcher Totalausfall.', 'Wholly absent hours/headcount distinction or no actual organisational-versus-financial participation analysis limits the total to14. An isolated wrong number, incomplete side effect or justified alternative rule is not total absence.', 'Q2')

material(3,'profile-requirements','E: Vierdimensionenprofil und veränderte Berufsanforderungen','E: four-dimension profiles and changing work requirements',
'Die lernende Person kann ein freiwillig gewähltes oder ausdrücklich simuliertes Vierdimensionenprofil mit zwei Paaren beruflicher Anforderungen vergleichen und begründete offene Klärschritte ableiten.',
'The learner can compare a voluntarily selected or explicitly simulated four-dimension profile with two pairs of work requirements and derive justified open clarification steps.',
'**A — ausdrücklich simuliertes Profil, keine Eignungsdiagnose.** Interesse: technischeProbleme lösen; Wert: verlässlicheZeiten; aktuelleFähigkeit: genaueDokumentation; Zukunft: regelmäßigeWeiterbildung. TechnischerServiceS: Fehlersuche, sorgfältigeProtokolle, wechselndeBereitschaftszeiten, technischeSchulungen. SachbearbeitungB: Genauigkeit, Kundenkommunikation, festeBürozeiten, WeiterbildunginVerwaltungsabläufen. DieseTätigkeitsprofile sind eigeneUnterrichtsdossiers, keinezugesagteStelle.\n\n**B — andere Simulation.** Interesse: analytischeAufgaben; Wert: gesellschaftlicherBeitrag; aktuelleFähigkeit: selbstständigDatenordnen, wenigErfahrungmitGruppenpräsentation; Zukunft: planbareWeiterbildung. DatenanalyseD: Auswerten, dokumentieren, Teamabstimmung, wechselndeProjektfristen. SozialeBeratungC: intensiveInteraktion, Dokumentation, vertraulicherUmgangmitInformationen, geregelteFallbesprechung. NeueInformation: DführtjedeWocheeineTeampräsentation durch; CbietetgeleiteteÜbungenfürGesprächsführung. Fähigkeitenkönnenentwickeltwerden.',
'**A — explicitly simulated profile, no aptitude diagnosis.** Interest: technical problems; value: predictable time; current ability: accurate documentation; future: regular training. Technical service S requires troubleshooting, careful records, variable on-call hours and technical courses. Office role B requires accuracy, customer communication, fixed office hours and administrative training. These are original teaching dossiers, not job offers.\n\n**B — different simulation.** Interest: analytical tasks; value: social contribution; current ability: independently organising data, limited group-presentation experience; future: predictable further training. Data analysis Drequires analysis, records, teamwork and varying project deadlines. Social counselling Crequires intensive interaction, records, confidential information handling and scheduled case discussions. New information: Dhas weekly team presentations; Coffers guided conversation practice. Skills can develop.',
[
step('Lege fürA eineVierdimensionen-Vergleichstabelle fürS/B an; benennein jederDimension konkreteAnforderung undPassung/Spannung.', 'Create A’s four-dimension comparison for S/B, identifying actual demands and matches/tensions in each dimension.', 'TechnikinteressepasstzuS,KommunikationinBoffen;ZeitwertkollidiertmitSBereitschaft,passtzuB;GenauigkeitträgtbeideDokumentationen;WeiterbildungswunschpasstzujeanderenInhalten. EinTätigkeitslabel allein istkeinVergleich.', 'Technical interest fits Swhile Bcommunication is open; time predictability conflicts with Son-call hours and fits B; accuracy aids both; future learning concerns distinct technical/administrative content. Labels alone are not comparison.', ['InteressemitbeidenAnforderungen','WertmitbeidenAnforderungen','aktuelleFähigkeitmitbeidenAnforderungen','ZukunftmitbeidenAnforderungen']),
step('Begründe fürA einevorläufigePräferenzundeinentwickelbarenBereich. TrenneInteresse vonnachgewiesenerFachkompetenz.', 'Justify A’s tentative preference and a developable area; distinguish interest from demonstrated competence.', 'SoderBistbedingtvertretbar:etwaSbeiKlärungderBereitschaftoderBbeiLernenkommunikativerRoutinen. TechnischeNeugierbeweistkeineFehlersuchkompetenz;GenauigkeitistnurAnhaltspunkt.Fähigkeitkannentwickeltwerden,keinstarresEignungsurteil.', 'Either is conditionally defensible: Ssubject to on-call clarification or Bwith communication development. Technical interest proves no troubleshooting competence; accuracy is limited evidence. Alearnable area is not fixed unfitness.', ['fallbezogenePräferenz','begründetePassung/Spannung','konkreterLernbereich','Interesse≠Kompetenz/festeEignung']),
step('Plane fürA einenprüfbarenKlärschritt fürbeideOptionenundstellezwei gezielteFragen. WarumistkeineZugangszusagebelegt?', 'Plan a checkable clarification for both Aoptions and two focused questions; explain why admission is unproven.', 'SimuliertesTätigkeitsprotokolloderbereitgestellteHospitationsbeschreibungmitS/Bvergleichen;FragenzuhäufigenBereitschaftenundKundenkommunikation/Weiterbildung. ProfilmaterialnenntkeineZulassungoderBewerbungserfolg. KeinenrealenKontaktdurchführen.', 'Compare a simulated activity record/supplied shadowing account with both S/B; ask about on-call frequency and communication/training. These profiles establish no admission or application success. No real contact is required.', ['KlärschrittfürS','KlärschrittfürB','gezielteFragenmitInformationszweck','keineZugangs-/Erfolgszusage']),
step('VergleicheB erneutinallevierDimensionenmitD/C. Berücksichtige,dassgesellschaftlicherBeitragundselbstständigeArbeitkeineeinzigeBerufswahlbestimmen.', 'Compare all four Bdimensions with D/C; avoid treating social contribution or independence as a unique job assignment.', 'AnalytikpasstzuDundmöglichauchFallstrukturierunginC;BeitragkanninbeidenTätigkeitenentstehen.GenauesDatenordnennutztD/C-Dokumentation,Präsentation/InteraktionbleibenLernfelder.WeiterbildungundProjekt-/Fallzeiten sindzuprüfen;SelbstständigkeitheißtnichtohneTeam.', 'Analysis fits Dand possibly case organisation in C; social contribution can occur in both. Data organisation aids records; presentation/interaction are learning areas. Examine training and project/case times; independence does not mean no team.', ['InteressebeideProfile','WertbeideProfile','FähigkeitenbeideProfile','ZukunftmitRahmenbedingungen']),
step('ÜberarbeiteB-VergleichnachderneuenInformation. NenneeineerlernbareFähigkeitundeineverbleibendeoffeneFrage.', 'Revise B’s comparison using new information; name a learnable skill and an unresolved question.', 'DfordertnunexplizitwöchentlichePräsentation,alsoerhältKommunikationslernenmehrGewicht;C-ÜbungenöffnenEntwicklungsweg.Statt„analytisch=alleinarbeiten“konkreteÜbung/Feedbackplanen;FrageetwanachTrainingszeitenoderProjektfristenbleibtoffen.', 'D’s weekly presentation increases communication-learning relevance; C’s guided practice offers development. Replace “analysis=working alone” with practice/feedback; clarify training time or project deadlines.', ['neueD-Anforderungverarbeitet','C-Entwicklungschanceverarbeitet','konkreteerlernbareFähigkeit','echteoffeneInformationsfrage']),
step('BegründeB einenangepasstenErkundungsplanmiteinerAlternativeundbenenneMaterialgrenzen. DarfeinfiktivesProfilalsdeineechteDiagnoseausgegebenwerden?', 'Justify B’s adapted exploration plan with an alternative and evidence limits; may a simulation be presented as your actual diagnosis?', 'EtwakleineAnalysemitTeampräsentationundsimulierteBeratungseinheitvergleichen,vorläufigD/Coffenhalten. DasgegebeneProfilistSimulation,TätigkeitsdossiersbelegenkeinePersoneneignung;persönlicheAngabenbleibenlokal. AlternativeUrteilemitgleicherBegründungzählen.', 'Compare a small analysis/team presentation with a simulated counselling exercise, keeping DorCopen. The supplied profile is simulated and dossiers establish no personal aptitude; private facts stay local. Alternative reasoned choices count.', ['angepassterPlan','begründeteAlternative','SimulationundEvidenzgrenze','offeneOrientierungstattDiagnose'])
], 'Fehlt über die gesamteArbeit ein tatsächlicher mehrdimensionaler Anforderungsvergleich vollständig, oder werden Profile durchgehend als starre Eignungszertifikate behandelt, gilt höchstens14. Eine einzelne unvollständige Dimension oder unsichere Präferenz zählt anteilig und löst diese Grenze nicht aus.', 'Wholly absent multidimensional requirements comparison or consistently treating profiles as fixed aptitude certificates limits the total to14; one incomplete dimension or tentative preference earns partial marks without that limit.', 'E')

material(4,'career-information','E: Informationsquellen, Fristen und revisierbare Zukunftsentwürfe','E: information sources, deadlines and revisable plans',
'Die lernende Person kann zwei fiktive Berufs- und Studienmaterialpakete zielgerichtet quellenkritisch nutzen und begründete Zukunftsentwürfe bei neuen Informationen überarbeiten.',
'The learner can purposefully and critically use two fictional career/study information packs and revise reasoned future plans after new information.',
'**Alle nachfolgenden Institutionen und Materialien sind datierte Simulationen, keine realen Zulassungsregeln. Aufgabenzeitpunkt10.10.2026.**\n\n**A — Ausbildungsfrage.** SimuliertesProfil: InteresseanTechnik,planbareWeiterbildung,wünschtVergleichzweierWege. M,Medienmagazin„Berufsblicke“,01.09.2026: einInterviewmitbegeisterterAuszubildender berichtetvielFehlersucheundKundenbesuche;derBeitragenthältWerbungfürBetriebe. B,Beratungsnotiz05.10.2026: Tätigkeit/ZeitenundKommunikationprüfen;AlternativekaufmännischeAusbildungerkunden;keineZusage. I,institutionellesBlattdesfiktivenAusbildungsverbunds07.10.2026: AusbildungT3Jahre,gegebenerAbschlussSundpraktischesAuswahlgespräch,zumModellbewerbungsschluss30.10.2026;AusbildungV2Jahre,AbschlussSundschriftlicheÜbung,Frist20.11.2026. BeidehabenWeiterbildungsmöglichkeiten,konkretePlätzenichtbelegt.\n\n**B — StudienfragemitUpdate.** SimuliertesProfil: analytischeAufgabenundgesellschaftlicherBeitrag,Zeitraumstart2027. F,Forumserfahrung12.06.2023:„AllemitSdürfeneinfachohneAuswahlstudieren“. H,HochschulblattderfiktivenHochschuleR08.10.2026: StudienwegDverlangtSundAuswahlgespräch;Bewerbungbis15.01.2027,nurvollständigeUnterlagenberechtigenzurTeilnahme,keineZusage. N,Beratungsnotiz09.10.2026: alternativberuflicheAusbildungC,Interaktionsanforderungenprüfen. NeueI-Information10.10.2026: fristgerechteBewerbungfürDverlangtzusätzlichSprachnachweisX;dasProfilhatXnoch nicht. ObNachreichenmöglichist,stehtnichtimMaterial.',
'**All following institutions/materials are dated simulations, not real admission rules. Task date10October2026.**\n\n**A — training question.** Simulated profile: technical interest, predictable further learning, wishes to compare two routes. M,magazine “Career Views”,1September2026: one enthusiastic trainee describes troubleshooting/client visits, alongside employer advertising. B,advice note5October2026: investigate tasks/times/communication; explore administrative training as an alternative; no offer. I,fictional training consortium sheet7October2026: route Tlasts3years, requires given qualification Sand practical selection interview, model deadline30October2026; Vlasts2years, requires Sand written exercise, deadline20November2026. Both offer further-learning options, but places are unproven.\n\n**B — study question with update.** Simulated profile: analysis/social contribution, intended2027start. F,forum12June2023:“Everyone with Scan study without selection”. H,fictional universityR sheet8October2026:Drequires Sand selection interview; apply by15January2027; complete documents allow selection participation, not guaranteed admission. N,advice9October2026:suggests trainingC and examining interaction demands. New Iinformation10October2026: on-time Dapplications also require language evidenceX; the profile lacks X. The dossier does not say whether later submission is allowed.',
[
step('Nutze fürA Medien,BeratungundInstitution jeweilsfür einekonkreteFrageundbewertedazuDatum,HerausgeberundInteresse.', 'Use A’s media, advice and institution for one concrete question each; evaluate dates, publishers and interests.', 'MliefertkritischTätigkeitsbild,aberEinzelfallerfahrung/Werbung;BhilftReflexion/Alternativen,nichtZulassung;IbestimmtimModellZugang/Dauer/Fristen.JüngereDatumalleingarantiervollständigeInformationnicht;FunktionenundInteressenvergleichen.', 'Musefully informs a critical work picture but is anecdotal/advertising; Bsupports reflection/options, not admission; Ispecifies model requirements/duration/deadlines. Later dates alone guarantee no completeness; compare authority/functions.', ['gezielteMedienfrageundGrenze','gezielteBeratungsfrageundFunktion','gezielteInstitutionsfrageundAutorität','Datum/Herausgeber/Interessekritisch']),
step('Erstelle fürA einInformationsprotokollmitzweiüberprüfbarenNachfragenundeinerFristfolge,ohneeinenrealenKontaktaufzunehmen.', 'Create A’s information log with two checkable follow-up questions and deadline sequencing, without real contact.', 'EtwaQuelleM/Datum/FragezuBereitschaftszeiten,QuelleI/Datum/FragezuAuswahlunterlagen,simulierteB-FragezurAlternative.PrüfungTvor30.10,dannVvor20.11;ausAufgabenzeitpunktbleiben20bzw41Kalendertage.DokumentierenistkeineKontaktbestätigung.', 'Record M/date/question on working times and I/date/question on selection documents, with simulated advice on V. Investigate Tbefore30October and Vbefore20November;20and41calendar days remain. Aplan is not a confirmed contact.', ['nachvollziehbaresQuellenprotokoll','zweiFragenmitPrüfzweck','T/V-Fristfolge','Plan≠wirklicheKontaktaufnahme']),
step('Leite fürA einenbegründetenvorläufigenZukunftsentwurfmitAlternativeundZugangsbedingungab. WasliefertdasInterviewgeradenicht?', 'Derive A’s reasoned provisional plan with alternative/entry condition; what does the interview fail to establish?', 'TistbeitechnischemInteressebedingtplausibel,Zeiten/Kommunikationprüfen;VistandersbegründeteAlternative,entsprechendeAuswahlangehen.Dauer/Frist/ZugangausI,höhereAutoritätalsAnekdote.InterviewbeweistwederallgemeinenAlltagnochAufnahme;anderegewichteteUrteilezählen.', 'Tconditionally suits technical interest subject to hours/communication; Vis a reasoned alternative with separate selection. Take duration/deadline/entry from I, not an anecdote. The interview proves neither general daily work nor admission; other reasoned choices count.', ['begründeterT/V-Entwurf','tatsächlicheAlternative','institutionelleZugangsbedingung','MedienanekdoteohneZusage']),
step('Löse fürB denKonfliktzwischenFundH. NutzeNfürdieeigeneFunktionundbenennekonkreteoffeneInformation.', 'Resolve B’s F/Hconflict, use Nfor its own function and identify specific open information.', 'Fvon2023istunverbindlicheErfahrungundwidersprichtaktuellemH-Auswahlverfahren.HdefiniertModellbedingungen.NkannC/Tätigkeitspassungklären,keineH-Zusage.OpenistAuswahlablauf/Unterlagen/Sprachnachweis-Nachreichregel.', 'F’s2023anecdote is non-binding and conflicts with H’s current selection. Hstates model requirements; Nsupports alternative C/fit, not university admission. Clarify selection/documents or language-evidence submission rules.', ['ältereForumsaussagekritisch','aktuellesHpriorisiert','BeratungfürAlternativegenutzt','gezielteoffeneFrage']),
step('ÜberarbeiteB-PlanaufgrundI-UpdateX. DokumentiereeineechtePlanänderung,FristundnächstenInformationsschritt;erfindekeineNachreichzulassung.', 'Revise B’s plan after the Xupdate; document actual change, deadline and next information step without inventing later-submission permission.', 'PlanDbleibtbedingt:fehlendesXfesthalten,vor15.01.2027Nachreich-/ErwerbsbedingungenimgegebenenModellprüfen;ggfC-Alternativeausbauen.VorhervoraussetzungsarmerPlanzu„Xzuerstklären“ändern.NichttrotzunvollständigerUnterlagenZulassungbehaupten.', 'Dbecomes conditional: record absent X, clarify acquisition/later-submission conditions before15January2027 and develop Cas needed. Explicitly revise the previous plan to resolving Xfirst; incomplete documents justify no admission claim.', ['fehlendesXberücksichtigt','konkretePlanänderung','FristundInformationsschritt','keineerfundeneNachreich-/Zusage']),
step('BegründeB-ZukunftsentwurfmitAlternativeundInformationsgrenze. WarumbelegtkeinederQuelleneinenrealenStudienplatz?', 'Justify B’s future plan with an alternative/evidence limit; why does no source establish a real study place?', 'DkannanalytischesInteresseaufgreifen,CgesellschaftlicheInteraktion;Anforderungen/LernmöglichkeitengegeneigenesodermodelliertesProfilabwägen.H/IzeigenModellzugang,keinenPlatz;BeratungkeineEntscheidung.AlleInstitutionensindSimulation,keinKontakt/Erfolgistbelegt.', 'Dcan support analytical interest and Csocial interaction; weigh demands/learning against the selected profile. H/Istate model entry, not an offer; advice is no admission decision. Institutions are fictional and no real contact/success is established.', ['bedingterbegründeterEntwurf','begründeteAlternative','Informationsfunktionenunterschieden','Simulations-/Zusagegrenze'])
], 'Fehlt vollständig jede zielgerichtete Nutzung der unterschiedlichen Medien-, Beratungs- und Institutionsfunktionen, oder wird über die ganze Arbeit kein begründeter Zukunftsentwurf mit Informationsfolge entwickelt, gilt höchstens14. Eine unvollständige Rückfrage oder ein Datumsfehler löst diese Grenze nicht aus.', 'No purposeful use of distinct media/advice/institution functions anywhere, or no reasoned future plan with an information sequence, limits the total to14; one incomplete question/date error does not.', 'E')

AIURL='https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/KI-unterstuetzte-Arbeit'
HOMEURL='https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/F2580-2'
material(5,'current-work-changes','E: KI-Assistenz und hybride Arbeit begründet beurteilen','E: reasoned evaluation of AI assistance and hybrid work',
'Die lernende Person kann anhand zweier datierter BAuA-Primärkontexte Chancen und Risiken veränderter Arbeit in unterschiedlichen Tätigkeiten beurteilen und offene eigene oder simulierte Erkundungsschritte begründen.',
'The learner can use two dated primary BAuA contexts to evaluate changing work across tasks and justify open personal or simulated exploration steps.',
f'**A — empirischer Kontext, eigener begrenzter Paraphrasenauszug.** [BAuA, KI-unterstützte Arbeit](https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/KI-unterstuetzte-Arbeit), Bericht2025, DOI10.21934/baua:berichtkompakt20251009; DiWaBe2.0-Erhebung2024. Die Befragungsanalyse verbindet KI-Arbeit mit mehr Handlungsspielraum und zugleich höherer Intensität; sie beweist keine Kausalwirkung.\n**A — eigene fiktive Ergänzung.** Kundenservice: SuchzeitjeAnfrage sinkt20→12Minuten; paralleleAnfragen steigen3→5.MenschlicheFehlerprüfungbleibtnötig;Entscheidungsspielraumistgegeben,aberZeitdruckkannsteigen.SimulierteOrientierung: InteresseanInformationsklärung,StärkeGenauigkeit,Kommunikationnochüben.\n\n**B — anderer empirischer Kontext, begrenzte eigene Paraphrase.** [BAuA, Arbeit von zu Hause](https://www.baua.de/DE/Angebote/Publikationen/Bericht-kompakt/F2580-2), Bericht2026, DOI10.21934/baua:berichtkompakt20260102; Arbeitszeitbefragung2023. Betriebliche Vereinbarungen gehen mit mehr Flexibilität/besserer Vereinbarkeit einher; fehlende Regeln häufiger mit Entgrenzung. Das ist kein Kausal- oder Individualbeweis.\n**B — eigene fiktive Ergänzung.** Entwicklungsbetrieb: Bildschirmarbeitkann2von5Tagenhybrid erfolgen,ProduktionnurvorOrt. Bei2HybridtagenspartdieBildschirmrolle2×60=120MinutenPendelzeit/Woche,verlagertnichtdieProduktion.Zusammenarbeit10–14Uhr, NachrichtenamAbendohneAntwortpflicht;dieLeitungmussdasauchumsetzen.StändigeNachrichtenkönnenAbgrenzungbelasten.SimulierteOrientierung: InteresseanProduktentwicklung,WertverlässlicheErholung,nochwenigErfahrungmitdigitalerKooperation. Primärkontextewurdenam10.10.2026 frisch über den lesbaren amtlichen Suchindex geprüft; direkte Seitenabrufe waren403, keine vollständigePDFlektüre behauptet.',
f'**A — empirical context, limited original paraphrase.** [BAuA AI-supported work]({AIURL}), report2025, DOI10.21934/baua:berichtkompakt20251009; DiWaBe2.0survey2024. Survey analysis associates AIwork with greater autonomy and higher intensity together; it proves no causal effect.\n**A — original fictional supplement.** Customer service: search time per enquiry falls20→12minutes; simultaneous enquiries rise3→5.Human error checking remains necessary; discretion may improve while time pressure rises. Simulated orientation: interest in clarifying information, accuracy strength, communication still to practise.\n\n**B — different empirical context, limited original paraphrase.** [BAuA working from home]({HOMEURL}), report2026, DOI10.21934/baua:berichtkompakt20260102; working-time survey2023. Agreements are associated with more flexibility/better work-life fit; absent rules more often with blurred boundaries. This establishes no individual or causal proof.\n**B — original fictional supplement.** Development firm: screen tasks can be hybrid2of5days, production must be on site. Two hybrid days save2×60=120commuting minutes/week for the screen role, not production. Team contact10:00–14:00; evening messages require no answer, with actual management implementation necessary. Constant messages may burden boundaries. Simulated orientation: product-development interest, value of reliable recovery and little digital-cooperation experience. Primary contexts were freshly checked10October2026 through readable official indexed content; direct pages returned403, with no full-PDF reading claim.',
[
step('Ordne inA Berichtjahr,Erhebungsjahr,empirischeAussageundFallannahmezu. BerechneSuchzeitentlastungundbewertedieBehauptung„KIverursachtimmerwenigerBelastung“.', 'Identify A’s report/survey years, empirical statement and fictional assumption; calculate search-time relief and assess “AIalways causes less strain”.', '2025Bericht/2024Erhebung;beideArbeitsqualitätszusammenhängesindempirisch,20→12fiktiv.Suchzeitsinkt8Minuten=40%;mehrParallelitätkannentlastungüberlagern.Kausalität/„immer“folgtwederausBefragungnochEinzelfall.', 'Report2025/survey2024; the work-quality associations are empirical, while20→12is fictional. Search time falls8minutes=40%; concurrency can offset relief. Neither survey nor case proves causality or “always”.', ['Bericht2025/Erhebung2024','empirischgegenfiktivgetrennt','8Minuten/40%','begründeteKausal-/Pauschalgrenze']),
step('WägefürA Entlastung,Handlungsspielraum,IntensivierungundFehlerverantwortungab. Begründe einekonkreteGestaltungsbedingung.', 'Weigh A’s relief, autonomy, intensification and error responsibility; justify one concrete design condition.', 'InformationssuchewirdkürzerundWahlmöglichkeitenkönnenhelfen;3→5Parallelität(+66,7%)/Unterbrechungenerhöhendruck.FachlicheFehlerprüfungbleibtmenschlicheArbeit.BegrenzteParallelität,PrüfzeitundUnterstützungkönnenVorteiletragbar machen;keinNettoeffektautomatisch.', 'Faster search/discretion may help; concurrency rises3→5(+66.7%)and interruptions may increase strain. Human domain checks remain necessary. Limit concurrency, allow checking time/support; no automatic net benefit follows.', ['Entlastung/Autonomiefallbezogen','Intensivierungsmechanismus','Fehlerverantwortung','begründeteGestaltungsbedingung']),
step('LeitefürA auseigenenfreiwilligenBezugspunktenoderausSimulation einenbegründetenErkundungs-undLernschrittab. Wasbleibtoffen?', 'Use voluntary personal points or A’s simulation to derive a justified exploration and learning step; identify what remains open.', 'Genauigkeit/InformationsinteressemitPrüfaufgabenverbinden,konkreteServiceabläufeimUnterrichtsdossiererkundenundKommunikation/Fachprüfungüben.NachrealerPrüfzeitundParallelitätsregel fragen,bloßPlan.KeinJobverlust-/ErfolgsorakelundkeinprivaterKontakt.', 'Connect accuracy/information interest to checking, explore service workflows in supplied dossiers and practise communication/domain checks. Clarify actual checking time/concurrency rules as a plan. No job-loss/success prediction or real private contact.', ['gewählterProfil-/Interessenbezug','fallbezogenerErkundungsschritt','konkreterKompetenzlernSchritt','offeneFrageohneJobvorhersage']),
step('OrdneB QuellenjahreundGrenzenzu,berechnePendelentlastungundvergleicheZugangbeiBildschirm-/Produktionsarbeit.', 'Identify B’s source years/limits, calculate commuting relief and compare screen/production access.', '2026Bericht/2023Erhebung;120MinutenEntlastungistnurFiktionfürBildschirmrolle.BefragungszusammenhangbeweistnichtWirksamkeitjederRegel.Produktionkannhiernichtortsflexibelarbeiten,gleichesUnternehmenheißtnichtgleicheChance;andereGestaltungvorOrtbleibtoffen.', 'Report2026/survey2023;120minutes is fictional screen-role relief. Association proves no universal rule effectiveness. Production cannot be location-flexible here; the same firm gives unequal access, with other on-site design options open.', ['Bericht2026/Erhebung2023','empirischeGrenze','120MinutenmitFallabgrenzung','ungleicheTätigkeitszugänge']),
step('BeurteileB Flexibilität,Abgrenzung,KooperationundErholung. PrüfedievereinbartenKontaktregelnunddiekeineAntwortpflichtamAbend.', 'Evaluate B’s flexibility, boundaries, cooperation and recovery; assess contact rules and no evening reply duty.', 'WenigerPendeln/Zeitwahlkannhelfen;Nachrichten,IsolationoderKoordinationkönnenbelasten.10–14FensterunterstütztZusammenarbeit,brauchtUmsetzungundfaireProduktionsabstimmung.KeineAntwortpflichtschütztpotenziellErholung,nurwennErwartungen/Leitungdaspassen;keinegenerelleÜberlegenheit.', 'Less commuting/time choice may help, while messages, isolation or coordination can burden. The10–14window supports teamwork with implementation and fair production coordination. No reply duty may protect recovery if management/expectations respect it; hybrid work is not universally superior.', ['Flexibilitätschance','Abgrenzungs-/Kooperationsrisiko','konkreteKontaktregelmitUmsetzung','Erholung/ungleicheGestaltungbegründet']),
step('EntwicklefürB einebedingteOrientierungsfolgeundAlternativeauseinemfreiwilligenodersimuliertenProfil. TrenneModellbetriebvonDeutschlandtrend.', 'Derive B’s conditional career implication and alternative from voluntary/simulated points; distinguish the model firm from a national trend.', 'Produktinteresse/ErholungswertmitbeidenRollenprüfen,digitaleAbsprachenübenundFragenzuErreichbarkeit/Arbeitszeitenstellen;vorOrtOptionmitverlässlicherPlanungistAlternative.EinBetriebsfallbeweistkeinenDeutschlandtrendoderpersönlicheEignung;begründeteandereOrientierungenzählen.', 'Examine product interest/recovery values across roles, practise digital coordination and clarify availability/hours; predictable on-site work is an alternative. One firm proves no national trend or personal aptitude; other reasoned orientations count.', ['Profilbezug','bedingteErkundungs-/Lernfolge','begründeteAlternative','Fall-/Trend-/Eignungsgrenze'])
], 'Fehlt über die ganzeArbeit eine tatsächliche Chancen-/Risikenabwägung vollständig, oder fehlen sämtliche begründeten Konsequenzen für eine eigene beziehungsweise ausdrücklich simulierte berufliche Orientierung, gilt höchstens14. Eine unvollständige Grenze oder einzelne missglückte Quellenjahresangabe zählt anteilig; nachweisbare Leistung an anderer Stelle gilt.', 'Wholly absent opportunities/risks evaluation or no justified personal/explicitly simulated career implications anywhere limits the total to14. One incomplete limit or wrong source year earns partial credit; evidence elsewhere counts.', 'E')

material(6,'entrepreneur-employee-reflection','E: Unternehmer- und Beschäftigtenrollen offen vergleichen','E: openly comparing entrepreneur and employee roles',
'Die lernende Person kann freiwillig gewählte oder ausdrücklich simulierte Interessen und Stärken mit Unternehmer- und Beschäftigtenrollen in zwei Tätigkeitsfeldern vergleichen und Erkundungsschritte bei neuen Interessen anpassen.',
'The learner can compare voluntary or explicitly simulated interests and strengths with entrepreneurial and employee roles in two fields and adapt exploration to new interests.',
'**A — Reparatur, eigene fiktive Profile.** GemeinsameAnforderungenanSelbstständigkeitundBeschäftigtenrolle:Auftragsklärung,sichereFacharbeit,DokumentationundKooperation.SelbstständigerDienstergänztAkquise,Planung,FinanzierungundBetriebsverantwortung;angestelltesTeamhatvereinbarteZuständigkeitenundarbeitetebensokundenorientiert.SimulierteBezugspunkte:InteresseansorgfältigerpraktischerArbeit,StärkeGenauigkeit,Finanzierungskenntnissenochweniggeübt.ZweiRollenmüssenoffengehaltenwerden;keinePersönlichkeitsdiagnose.\n\n**B — digitaleGestaltung, andererFall.** AngestellteRolle:Kundengespräche,Grafikentwicklung,TeamabstimmungundFristen.EigeneAgenturergänztAkquise,Kalkulation,FinanzierungundTeamkoordination;auchAngestellteorganisierenTeilaufgaben.SimulierteBezugspunkte:Gestaltungsinteresse,StärkevisuelleErklärung,neu entdecktesInteresseanTeamorganisation,nochwenigKalkulationserfahrung. Fähigkeitenkönnenentwickeltwerden;dieProfilebeweisennichteinenpassendenBerufoderGründungserfolg.',
'**A — repair, original fictional roles.** Both self-employment and employment require order clarification, safe skilled work, records and cooperation. An independent repair service adds client acquisition, planning, finance and business responsibility; an employed team has agreed responsibilities and also works with customers. Simulated points: interest in careful practical work, accuracy strength, little financing practice. Keep both roles open; this is no personality diagnosis.\n\n**B — digital design, different case.** Employed role: client conversations, graphics, teamwork and deadlines. An own agency adds acquisition, costing, finance and team coordination; employees also organise some tasks. Simulated points: design interest, visual explanation strength, newly discovered team-organisation interest and limited costing experience. Skills can develop; profiles prove no uniquely fitting job or business success.',
[
step('VergleicheA-Interesse/StärkenmitgemeinsamenundunterschiedlichenAnforderungenderbeidenRollen. NutzekonkreteTätigkeitenstattPersönlichkeitsetiketten.', 'Compare A’s interests/strengths with both roles’ shared/distinct demands using actual tasks rather than personality labels.', 'Sorgfalt/GenauigkeitpasstpotenziellzuFacharbeit/DokumentationbeiderRollen;Akquise/FinanzierungistzusätzlicheGründungsanforderung,Kooperationgiltbeiden.TatsächlicherVergleichbrauchtBezugspunkteundTätigkeiten,kein„kreativ=Chef“.', 'Care/accuracy may support skilled work/records in both roles; acquisition/finance are additional entrepreneurial demands and cooperation is shared. Connect selected points to actual tasks, not “creative=boss”.', ['gewählteInteressen/Stärken','gemeinsameAnforderungen','zusätzlicheGründungsanforderungen','konkreterVergleichbeiderRollen']),
step('BenennefürA einePassungundeinentwickelbarenBereich. Prüfe„wenigFinanzwissen=ungeeignet“und„Interesse=Fachkompetenz“.', 'Name A’s match/developable area and assess “little finance knowledge=unfit” and “interest=competence”.', 'GenauigkeitistbegrenzterPassungshinweis;FinanzplanungistlernbarerBereich.InteressebeweistkeinefachlichsichereReparatur,fehlendeErfahrungkeinendauerhaftenAusschluss.Sicherheitmussgelernt/geprüftwerden,nichtPersönlichkeitvergeben.', 'Accuracy offers limited fit evidence; financing is learnable. Interest does not prove safe repair competence, and limited experience means no permanent exclusion. Skills need learning/checking, not personality labels.', ['begründetePassung','konkreterentwickelbarerBereich','keinNichteignungsautomatismus','Interesse≠nachgewieseneKompetenz']),
step('BegründeA einennächstenErkundungsschrittfürbeideRollenundvorläufigeOrientierungmitGrenze. EswirdkeinrealerKontaktverlangt.', 'Justify A’s next exploration for both roles and tentative orientation with a limit; no real contact is required.', 'SimulierteBetriebsgespräche/TätigkeitsdossiersbeiderRollenanAuftragsklärungundFinanzplanungvergleichen,eineLernübungplanen.BeschäftigungoderSelbstständigkeitbedingtbegründbar;keinesichereEignungs-/Erfolgszusage.AuchruhigePersonenkönnenAkquiselernen.', 'Compare supplied simulated conversations/task dossiers for both roles on orders/finance, and plan a learning exercise. Either role is conditionally defensible, without aptitude/success guarantees; quieter people can learn acquisition.', ['ErkundungbeiderRollen','konkreteInformations-/Lernfrage','begründetevorläufigeOrientierung','offeneEignungs-/Erfolgsgrenze']),
step('VergleicheB-eigeneodersimulierteBezugspunktemitbeidenGestaltungsrollenundnennedreiTätigkeitsanforderungen.', 'Compare B’s selected personal/simulated points with both design roles and name three work demands.', 'VisuelleErklärungunterstütztGrafik/KundengesprächeinbeidenRollen;Fristen/Teamabstimmungsindgemeinsam.AgenturergänztAkquise/Kalkulation/Finanzierung,ohneAngestelltealsunorganisiertzubehandeln.NeueOrganisationkannbeideRollenstützen.', 'Visual explanation may aid graphics/client conversations in both roles; deadlines/teamwork are shared. The agency adds acquisition/costing/finance without implying employees never organise. Organisation interest can support either.', ['gewählteB-Bezugspunkte','gemeinsameGestaltungsanforderungen','zusätzlicheAgenturanforderungen','begründeterVergleichbeiderRollen']),
step('PrüfedieneueInformation„Teamorganisationinteressiertmich“. PasseeinenErkundungs-/Entwicklungsschrittwirklichan,stattnur„Agentur“zuwählen.', 'Use the new team-organisation interest to actually revise exploration/development, rather than merely selecting “agency”.', 'ZumaltenGestaltungsplanetwaeinekleineTeamaufgabemitRollen-/Zeitkoordinationergänzen,FeedbackauswertenundAgentur-/Angestelltenkoordinationgegenprüfen.Kalkulationgezieltüben;InteresseanOrganisationwirdsoerkundet,nichtalsBeweisbehandelt.', 'Add a small team scheduling/role exercise to the earlier design plan, review feedback and compare coordination in agency/employment. Practise costing; organisation interest is explored rather than treated as proof.', ['neuesInteressefallbezogen','tatsächlichePlanänderung','konkreteEntwicklungsübung','ErkundungstattInteressenbeweis']),
step('BegründeB eineoffeneOrientierungmitAlternativeundGrenze. WelcheZusatzinformationkönntedeinUrteiländern?', 'Justify B’s open orientation with an alternative/limit; what new information could change it?', 'EtwazunächstBeschäftigungmitTeamkoordinationerkundenundAgenturmitFinanzierungslernschrittalsAlternativehalten;oderumgekehrtmitGründen.Zeit/Risiko/Kundenarbeit/FinanzierungsanforderungenkönnenUrteiländern.FiktivesProfilbelegtkeineechtePerson,veränderteKompetenzenlassenWegeoffen.', 'For example, first explore employment/team coordination while retaining agency/finance learning as an alternative, or reverse with reasons. Time/risk/client/finance information may change the view. Fictional profiles diagnose no real person; developing skills keeps options open.', ['begründetevorläufigeOrientierung','tatsächlicheAlternative','urteilveränderndeInformationsfrage','offeneEntwicklungohneZuweisung'])
], 'Fehlt vollständig der tatsächliche Bezug eigener freiwilliger oder ausdrücklich simulierter Interessen/Stärken auf Anforderungen beider Rollen, oder wird über die ganzeArbeit kein begründeter Erkundungs-/Entwicklungsschritt abgeleitet, gilt höchstens14. Eine unvollständige Passung oder ungeklärte vorläufige Entscheidung ist kein Totalausfall.', 'Wholly absent links between voluntary/simulated interests/strengths and both roles’ demands, or no justified exploration/development step anywhere, limits the total to14. An incomplete match or undecided tentative choice is not total absence.', 'E')

